using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Playables;using UnityEngine.Animations;using UnityEngine.SceneManagement;
namespace Staff.Traversal.Editor {
public static class TangentAudition {
 public static readonly string[] Ids={"128670910","118110903","119840901","119830901","111080901","120480901","120470901","118130901"};
 public static AnimationClip Clip(string id){var p=AssetDatabase.FindAssets(id,new[]{"Assets/ThirdParty/MixamoLibrary"}).Select(AssetDatabase.GUIDToAssetPath).First(x=>x.EndsWith(".fbx"));return AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>().First(x=>!x.name.StartsWith("__preview__"));}
 public static void Run(){Directory.CreateDirectory("Library/TangentReview");var cat=AssetDatabase.LoadAssetAtPath<Staff.AnimationLab.AnimationLabCatalog>("Assets/StaffAnimationLab/Catalog.asset");var prefab=cat.characters.First(c=>c.name=="Kafka_NoCoat");foreach(var id in Ids){var clip=Clip(id);File.AppendAllText("Library/TangentReview/clips.txt",id+" "+clip.name+" "+clip.length+"s human="+clip.humanMotion+"\n");foreach(float phase in new[]{.15f,.4f,.65f,.85f})Capture(prefab,clip,phase,id);} }
 static void Capture(GameObject prefab,AnimationClip clip,float phase,string id){var scene=EditorSceneManager.NewPreviewScene();var graph=default(PlayableGraph);try{var go=UnityEngine.Object.Instantiate(prefab);SceneManager.MoveGameObjectToScene(go,scene);foreach(var mb in go.GetComponentsInChildren<MonoBehaviour>())mb.enabled=false;var a=go.GetComponentInChildren<Animator>();a.runtimeAnimatorController=null;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.Rebind();graph=PlayableGraph.Create();graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,clip);var o=AnimationPlayableOutput.Create(graph,"Pose",a);o.SetSourcePlayable(p);graph.Play();p.SetTime(clip.length*phase);graph.Evaluate(0);var bounds=new Bounds(a.GetBoneTransform(HumanBodyBones.Hips).position,Vector3.one*.1f);foreach(var r in go.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);var cg=new GameObject("Camera");SceneManager.MoveGameObjectToScene(cg,scene);var c=cg.AddComponent<Camera>();c.scene=scene;c.orthographic=true;c.orthographicSize=Mathf.Max(1.2f,bounds.size.y*.6f);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.13f,.16f,.2f);c.transform.position=bounds.center+new Vector3(2, .3f,-4);c.transform.LookAt(bounds.center);foreach(var angle in new[]{new Vector3(35,155,0),new Vector3(20,-40,0)}){var lg=new GameObject("Light");SceneManager.MoveGameObjectToScene(lg,scene);lg.transform.rotation=Quaternion.Euler(angle);var l=lg.AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.2f;}var rt=new RenderTexture(360,400,24);c.targetTexture=rt;c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(360,400,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,360,400),0,0);tex.Apply();File.WriteAllBytes("Library/TangentReview/"+id+"-"+phase.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png",tex.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}finally{if(graph.IsValid())graph.Destroy();EditorSceneManager.ClosePreviewScene(scene);}}
}
}
